def _extract_last_dict(text: str) -> str | None:
    stack = []
    start = None

    for i, ch in enumerate(text):
        if ch == "{":
            if not stack:
                start = i
            stack.append(ch)
        elif ch == "}":
            if stack:
                stack.pop()
                if not stack and start is not None:
                    # 找到一个完整 dict
                    candidate = text[start:i + 1]

    return candidate if 'candidate' in locals() else None


